#!/usr/bin/env python3
from __future__ import annotations

import base64
import gzip
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
UNIT_B64 = (
""
)
TEST_B64 = ""

def decode(payload: str) -> bytes:
    return gzip.decompress(base64.b64decode(payload))

unit_bytes = decode(UNIT_B64)
test_bytes = decode(TEST_B64)
source = ROOT / "data/course_redevelopment/electrofisica-electromecanica/units/unit-01.json"
mirror = ROOT / "data/generated_units/electrofisica-electromecanica/unit-01.json"
test = ROOT / "tests/test_electrofisica_electromecanica_unit_01_curated.py"
for path in (source, mirror, test):
    path.parent.mkdir(parents=True, exist_ok=True)
source.write_bytes(unit_bytes)
mirror.write_bytes(unit_bytes)
test.write_bytes(test_bytes)
assert source.read_bytes() == mirror.read_bytes()
assert b"Concepto de la unidad que debe definirse" not in unit_bytes
print("[ok] Electrofísica y Electromecánica U1 curada y espejo sincronizado")
